    subscriptions?: TSubscriptions;
    middlewares?: MiddlewareFunction<TInputContext, TContext, TMeta>[];
    errorFormatter?: ErrorFormatter<TContext, TErrorShape>;
    transformer?: CombinedDataTransformer;
  }) {
