      TParsedInput,
      TOutput,
      TParsedOutput
    >,
  ): Router<
    TInputContext,
    TContext,
    TMeta,
    Record<TPath, inferProcedureFromOptions<TInputContext, typeof procedure>> &
      TQueries,
    TMutations,
    TSubscriptions,
    TErrorShape,
    TTransformer
  >;

  public query<TPath extends string, TInput, TOutput>(
    path: TPath,
    procedure: CreateProcedureWithInput<TContext, TMeta, TInput, TOutput>,
  ): Router<
    TInputContext,
    TContext,
    TMeta,
    Record<TPath, inferProcedureFromOptions<TInputContext, typeof procedure>> &
      TQueries,
    TMutations,
    TSubscriptions,
    TErrorShape,
    TTransformer
  >;
}

